import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    static long modPow(long base, long exp) {
        long res = 1;
        for (long i = 0; i < exp; i++) {
            res = (res * base) % MOD;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long P = sc.nextLong();
        long K = sc.nextLong();

        boolean[] visited = new boolean[(int) P];
        long[] cycleCount = new long[(int) (P + 1)];

        if (K == 0) {
            long ans = 1;
            for (long i = 1; i < P; i++) {
                ans = (ans * P) % MOD;
            }
            System.out.println(ans);
            sc.close();
            return;
        }
        if (K == 1) {
            long ans = 1;
            for (long i = 1; i <= P; i++) {
                ans = (ans * P) % MOD;
            }
            System.out.println(ans);
            sc.close();
            return;
        }

        for (long start = 0; start < P; start++) {
            if (!visited[(int) start]) {
                long length = 0;
                long pos = start;
                while (!visited[(int) pos]) {
                    visited[(int) pos] = true;
                    length++;
                    pos = (K * pos) % P;
                }
                cycleCount[(int) length]++;
            }
        }

        long result = 1;
        for (long len = 2; len <= P; len++) {
            if (cycleCount[(int) len] != 0) {
                long base = (cycleCount[(int) len] * len + 1) % MOD;
                long power = 1;
                for (long i = 0; i < cycleCount[(int) len]; i++) {
                    power = (power * base) % MOD;
                }
                result = (result * power) % MOD;
            }
        }
        System.out.println(result);
        sc.close();
    }
}
